const quantile=(s,q)=>s.length?s[Math.floor((s.length-1)*q)]:null;
/** Measured wall-frame durations only; no engine FPS estimates or synthetic score. */
export class FrameLog{
 constructor({capacity=36000,spikeMs=50}={}){this.capacity=capacity;this.spikeMs=spikeMs;this.samples=[];}
 add(ms){if(Number.isFinite(ms)&&ms>0&&this.samples.length<this.capacity)this.samples.push(ms);}
 report(){const s=[...this.samples].sort((a,b)=>a-b),n=s.length,total=s.reduce((a,b)=>a+b,0),tail=s.slice(Math.max(0,n-Math.max(1,Math.ceil(n*.01))));return{frames:n,durationMs:total,averageFPS:n?1000*n/total:null,onePercentLowFPS:n?1000/(tail.reduce((a,b)=>a+b,0)/tail.length):null,medianMs:quantile(s,.5),p95Ms:quantile(s,.95),p99Ms:quantile(s,.99),worstMs:n?s[n-1]:null,spikes:s.filter(v=>v>this.spikeMs).length,worstSpikesMs:s.slice(-8).reverse(),distribution:[8.333,16.667,33.333,50,100,Infinity].map((max,i,a)=>({maxMs:Number.isFinite(max)?max:null,count:s.filter(v=>v<=(max)&&(!i||v>a[i-1])).length})),sampleLimited:n<100};}
}
export class BenchmarkRun{
 constructor({stages,warmup=5,seed=441,settings={},metadata={}}){if(!stages?.length||stages.some(s=>!(s.seconds>0)))throw Error('A benchmark needs timed stages');this.stages=stages.map(s=>({...s}));this.warmup=warmup;this.seed=seed;this.settings=structuredClone(settings);this.metadata=structuredClone(metadata);this.logs=this.stages.map(()=>new FrameLog());this.total=new FrameLog();this.elapsed=0;this.recorded=0;this.done=false;this.invalid=null;this.stage=0;}
 frame(ms){if(this.done||this.invalid||!Number.isFinite(ms)||ms<=0)return;this.elapsed+=ms/1000;if(this.elapsed-ms/1000<this.warmup)return;const t=this.recorded;let boundary=0,index=0;while(index<this.stages.length-1&&t>=boundary+this.stages[index].seconds){boundary+=this.stages[index].seconds;index++;}this.stage=index;this.logs[index].add(ms);this.total.add(ms);this.recorded+=ms/1000;if(this.recorded>=this.stages.reduce((n,s)=>n+s.seconds,0))this.done=true;}
 abort(reason){if(!this.done)this.invalid=reason;}
 result(){if(!this.done||this.invalid)throw Error(this.invalid||'Benchmark is incomplete');return{version:1,seed:this.seed,warmupSeconds:this.warmup,settings:this.settings,metadata:this.metadata,frameTimesMs:[...this.total.samples],overall:this.total.report(),stages:this.stages.map((s,i)=>({name:s.name,...this.logs[i].report()})),formula:'Average FPS = 1000 × frame count / sum(frame ms). 1% low = 1000 / mean(slowest ceil(1% of frames)). Percentiles use floor((N−1) × q). No synthetic score.'};}
}
export function recommendPreset(results,target=30){const passed=results.filter(r=>r.report.averageFPS>=target&&r.report.onePercentLowFPS>=target*.75&&r.report.p95Ms<=1000/target*1.35);return{preset:passed.at(-1)?.preset||'low',metTarget:passed.length>0,target};}
export function benchmarkCSV(result){const rows=[['stage','frames','average_fps','one_percent_low_fps','median_ms','p95_ms','worst_ms'],['overall',...['frames','averageFPS','onePercentLowFPS','medianMs','p95Ms','worstMs'].map(k=>result.overall[k])],...result.stages.map(s=>[s.name,...['frames','averageFPS','onePercentLowFPS','medianMs','p95Ms','worstMs'].map(k=>s[k])])];return rows.map(r=>r.map(v=>'"'+String(v??'N/A').replaceAll('"','""')+'"').join(',')).join('\r\n');}
